solution.Solution.cs:
public static class Fn
{
    public static Func<T, T> Pipeline<T>(params Func<T, T>[] steps) => input =>
    {
        T value = input;
        foreach (var step in steps) value = step(value);
        return value;
    };

    public static Func<T, TResult> Memoize<T, TResult>(Func<T, TResult> f) where T : notnull
    {
        var cache = new Dictionary<T, TResult>();
        return x =>
        {
            if (!cache.TryGetValue(x, out var result))
            {
                result = f(x);
                cache[x] = result;
            }
            return result;
        };
    }

    public static Action Once(Action action)
    {
        bool done = false;
        return () =>
        {
            if (done) return;
            done = true;
            action();
        };
    }
}

public record PriceChange(string Symbol, decimal Old, decimal New)
{
    public decimal Percent => Math.Round((New - Old) / Old * 100, 2, MidpointRounding.AwayFromZero);
}

public class StockTicker
{
    private readonly Dictionary<string, decimal> _last = new();

    public event EventHandler<PriceChange>? PriceChanged;
    public event EventHandler<PriceChange>? BigMove;

    public void Update(string symbol, decimal price)
    {
        bool known = _last.TryGetValue(symbol, out decimal old);
        _last[symbol] = price;
        if (!known || old == price) return;
        var change = new PriceChange(symbol, old, price);
        PriceChanged?.Invoke(this, change);
        if (Math.Abs(change.Percent) >= 5) BigMove?.Invoke(this, change);
    }
}

unitTests:
Test("pipelines", () =>
{
    var clean = Fn.Pipeline<string>(s => s.Trim(), s => s.ToLower(), s => s.Replace(' ', '-'));
    CheckEq(clean("  Hello World "), "hello-world");
    CheckEq(Fn.Pipeline<int>(x => x + 1, x => x * 10)(2), 30);
    CheckEq(Fn.Pipeline<int>()(7), 7);
});

Test("memoizing", () =>
{
    int calls = 0;
    var slowLength = Fn.Memoize<string, int>(s => { calls++; return s.Length; });
    CheckEq(slowLength("abc") + slowLength("abc") + slowLength("de"), 8);
    CheckEq(calls, 2);
});

Test("once", () =>
{
    int runs = 0;
    var init = Fn.Once(() => runs++);
    init(); init(); init();
    CheckEq(runs, 1);
});

Test("price events", () =>
{
    var ticker = new StockTicker();
    var changes = new List<string>();
    var big = new List<decimal>();
    object? sender = null;
    ticker.PriceChanged += (s, c) => { sender = s; changes.Add($"{c.Symbol} {c.Old}->{c.New}"); };
    ticker.BigMove += (_, c) => big.Add(c.Percent);

    ticker.Update("ACME", 100m);
    ticker.Update("ACME", 100m);
    ticker.Update("ACME", 103m);
    ticker.Update("ACME", 97.85m);
    ticker.Update("ZED", 10m);
    ticker.Update("ZED", 9m);

    CheckEq(changes, new[] { "ACME 100->103", "ACME 103->97.85", "ZED 10->9" });
    CheckEq(big, new[] { -5.00m, -10.00m });
    Check(ReferenceEquals(sender, ticker), "the sender should be the ticker");
    CheckEq(new PriceChange("X", 3m, 4m).Percent, 33.33m);
});

Test("unsubscribing", () =>
{
    var ticker = new StockTicker();
    int count = 0;
    EventHandler<PriceChange> handler = (_, _) => count++;
    ticker.PriceChanged += handler;
    ticker.Update("A", 1m);
    ticker.Update("A", 2m);
    ticker.PriceChanged -= handler;
    ticker.Update("A", 3m);
    CheckEq(count, 1);
});

